"""Saves IM Music logos from base64 (pre-downloaded from Google Drive) to assets/logo/"""
import base64
from pathlib import Path

WHITE_B64 = ""

BLACK_B64 = "iVBORw0KGgoAAAANSUhEUgAAAfQAAAH0CAYAAADL1t+KAAAAAXNSR0IArs4c6QAAIABJREFUeF7t3QnUZGV97//n1tVv9800IKAgGi+OiUqMJkQThwSjohEnXEBARFQcEIciEVHEISpBjBqMiuIQFUVRUCMqgyIiKiISRkWHIDjQjXTzdr/Vrqp7zv++1d2vb7rf97l1a+89XqdPnz69a63P8///91r73nuvbVhAAAEEEEAAgdYLOK3vAR1AAAEE"

out = Path("assets/logo")
out.mkdir(parents=True, exist_ok=True)

try:
    white_bytes = base64.b64decode(WHITE_B64)
    (out / "logo_white.png").write_bytes(white_bytes)
    print(f"White logo: {len(white_bytes)} bytes")
except Exception as e:
    print(f"White logo error: {e}")

try:
    black_bytes = base64.b64decode(BLACK_B64)
    (out / "logo_black.png").write_bytes(black_bytes)
    print(f"Black logo: {len(black_bytes)} bytes")
except Exception as e:
    print(f"Black logo error: {e}")
